def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_my, last_opp = history[-1]
    total_opp_d = opp.count('D')
    total_my_d = me.count('D')

    if n == 99:
        return 'D'

    if total_opp_d == 0:
        if n < 80:
            return 'C'
        if n == 80:
            return 'D'
        if n == 81:
            return 'C'
        return 'D'

    if total_opp_d == n:
        return 'D'

    recent = opp[-10:] if n >= 10 else opp
    opp_recent_d = recent.count('D')
    opp_recent_c = len(recent) - opp_recent_d

    opp_d_streak = 0
    for i in reversed(range(n)):
        if opp[i] == 'D':
            opp_d_streak += 1
        else:
            break

    after_d = 0
    d_after_d = 0
    after_c = 0
    d_after_c = 0
    for i in range(n - 1):
        if me[i] == 'D':
            after_d += 1
            if opp[i + 1] == 'D':
                d_after_d += 1
        else:
            after_c += 1
            if opp[i + 1] == 'D':
                d_after_c += 1

    p_d_after_d = d_after_d / after_d if after_d else 1.0
    p_d_after_c = d_after_c / after_c if after_c else 0.5

    if last_opp == 'C':
        if after_d >= 2 and p_d_after_d <= 0.5 and total_opp_d <= max(4, n // 8):
            return 'D'
        if after_d >= 2 and p_d_after_d < 0.35 and (n >= 50 or total_opp_d <= 6):
            return 'D'
        if n >= 90 and total_opp_d <= max(2, n // 10) and p_d_after_d < 0.55:
            return 'D'
        if n >= 82 and last_my == 'D' and total_opp_d <= max(2, n // 20) and p_d_after_d < 0.45:
            return 'D'
        return 'C'

    if opp_d_streak == 1 and n >= 2 and me[-2] == 'D' and opp[-2] == 'C':
        if opp_recent_c >= 4 or total_opp_d <= max(4, n // 5):
            return 'C'

    if opp_d_streak >= 2:
        if last_my == 'D' and opp_d_streak <= 4 and total_opp_d <= max(4, n // 8) and opp_recent_c >= 4:
            return 'C'
        return 'D'

    if last_my == 'D':
        if opp_recent_c >= 4 and total_opp_d <= max(3, n // 8):
            return 'C'
        return 'D'

    if total_opp_d <= max(1, n // 10) and opp_recent_c >= 7 and p_d_after_c <= 0.25:
        return 'C'

    if total_opp_d <= max(2, n // 12) and opp_recent_c >= 8:
        return 'C'

    return 'D'
